package cn.pulse.player;
import android.os.Looper;
import java.util.*;
import java.lang.reflect.*;
import org.json.*;

public final class DeviceLibraryCheck {
 static void check(boolean pass,String why){if(!pass)throw new AssertionError(why);}
 static class Memory implements PlaylistStore.Storage,ListeningHistory.Storage,FavoriteStore.Storage {String value="[]";public String read(){return value;}public void write(String s){value=s;}}
 static PlayerService.Track song(String title,String artist,String id){return new PlayerService.Track(title,artist,"https://example.test/"+id,180000);}
 static void rejected(Runnable task,String why){boolean failed=false;try{task.run();}catch(IllegalArgumentException e){failed=true;}check(failed,why);}
 static class Player extends PlayerService {int requested=-1;Player(DevicePlaybackRecoveryCheck.Store s){attachBaseContext(s);}public void play(int n){requested=n;index=n;}void update(){}}
 public static void main(String[] args){try{Looper.prepareMainLooper();run();System.out.println("PASS: independent playlists, CRUD, multi-list membership, persistence, atomic caps, history qualification/pause/replay/time, local discovery, network result filters, backup compatibility/idempotence and playlist playback");System.exit(0);}catch(Throwable t){t.printStackTrace();System.exit(1);}}
 static void run()throws Exception{
  PlayerService.Track a=song("晴天","周杰伦","a"),b=song("夜曲","周杰伦","b"),c=song("模特","李荣浩","c");
  Memory playlistDisk=new Memory(),likesDisk=new Memory();FavoriteStore favorites=new FavoriteStore(likesDisk);favorites.toggle(a);String likesSnapshot=likesDisk.value;
  PlaylistStore lists=new PlaylistStore(playlistDisk);String first=lists.create("最近在听"),second=lists.create("学习时听");check(lists.add(first,Arrays.asList(a,b,a))==2,"deduplicate sources within playlist");check(lists.add(second,Arrays.asList(a,c))==2,"same song can belong to multiple playlists");check(lists.remove(first,a.url),"remove from one playlist");check(lists.get(second).tracks.size()==2 && favorites.contains(a.url) && likesDisk.value.equals(likesSnapshot),"remove is independent of other playlist and favorites");
  lists.rename(first,"明天再听");PlaylistStore reopened=new PlaylistStore(playlistDisk);check(reopened.get(first).name.equals("明天再听") && reopened.get(first).tracks.get(0).url.equals(b.url),"rename and rows persist");
  reopened.get(second).tracks.clear();check(reopened.get(second).tracks.size()==2,"snapshot cannot mutate storage");reopened.delete(first);check(reopened.list().size()==1 && reopened.get(second).tracks.size()==2 && favorites.contains(a.url),"delete playlist retains song and likes");
  rejected(()->reopened.create("  "),"reject empty names");rejected(()->reopened.rename(second,new String(new char[41]).replace('\0','x')),"name limit");
  String snapshot=playlistDisk.value;int created=reopened.merge(new JSONArray(snapshot));check(created==0 && reopened.get(second).tracks.size()==2,"repeated playlist restore is idempotent");
  Memory capDisk=new Memory();PlaylistStore capped=new PlaylistStore(capDisk);String cap=capped.create("cap");ArrayList<PlayerService.Track> many=new ArrayList<>();for(int i=0;i<1001;i++)many.add(song("song"+i,"artist","many"+i));String before=capDisk.value;rejected(()->capped.add(cap,many),"cap at 1000 songs");check(before.equals(capDisk.value) && capped.get(cap).tracks.isEmpty(),"failed operation is atomic");
  Memory historyDisk=new Memory();ListeningHistory history=new ListeningHistory(historyDisk);ListeningSession session=new ListeningSession(history);long wall=2000000000L;
  session.sample(a,true,0,wall);session.sample(a,true,29000,wall+29000);check(history.ranked(wall+29000).isEmpty(),"quick skip doesn't train recommendations");session.sample(a,true,30000,wall+30000);check(history.ranked(wall+30000).get(0).plays==1,"30 seconds qualifies exactly once");
  session.sample(a,false,40000,wall+40000);session.sample(a,false,90000,wall+90000);check(history.ranked(wall+90000).get(0).millis==40000,"paused time excluded");session.sample(a,true,90000,wall+90000);session.sample(a,true,100000,wall-9999999);check(history.ranked(wall).get(0).millis==50000 && history.ranked(wall).get(0).plays==1,"wall clock jumps do not inflate time or plays");
  session.end(100000,wall);session.sample(a,true,110000,wall);session.sample(a,true,140000,wall+30000);check(history.ranked(wall).get(0).plays==2,"new playback qualifies again");session.sample(b,false,140000,wall);session.sample(b,false,999000,wall);check(history.ranked(wall).size()==1,"loading or silent seek contributes no time");
  ListeningHistory restoredHistory=new ListeningHistory(historyDisk);check(restoredHistory.ranked(wall).get(0).plays==2,"history restores");String historySnapshot=historyDisk.value;restoredHistory.merge(new JSONArray(historySnapshot));restoredHistory.merge(new JSONArray(historySnapshot));check(restoredHistory.ranked(wall).get(0).plays==2,"history restore uses maximum counts, not addition");
  ArrayList<MusicRecommendations.Seed> seeds=MusicRecommendations.seeds(history.ranked(wall),Arrays.asList(c));check(seeds.size()==2 && seeds.get(0).query.contains("周杰伦") && seeds.get(1).query.contains("李荣浩"),"qualified artist taste then favorite bootstrap");
  ArrayList<MusicRecommendations.Suggestion> local=MusicRecommendations.local(history.ranked(wall),Arrays.asList(a),Arrays.asList(a,b,c),a.url,Collections.emptySet(),0,wall);check(local.size()==1 && local.get(0).track==b && local.get(0).reason.contains("周杰伦"),"local discovery picks another song by preferred artist");
  check(MusicRecommendations.local(history.ranked(wall),Arrays.asList(a),Arrays.asList(a,b,c),a.url,new HashSet<>(Arrays.asList(b.url)),0,wall).isEmpty(),"dismissed candidates excluded locally");
  PlayerService.Track video=new PlayerService.Track("周杰伦 - 夜曲","B站 · uploader","bili:BV1FPjy6TEiE",180000),sameVideo=new PlayerService.Track("分集","B站","bili:BV1FPjy6TEiE?cid=123",180000);
  check(!MusicRecommendations.eligible(video,Arrays.asList(sameVideo),Collections.emptySet(),Collections.emptyList()),"known multipart video filtered by stable source");check(!MusicRecommendations.eligible(video,Collections.emptyList(),new HashSet<>(Arrays.asList(video.url)),Collections.emptyList()),"dislikes filter online results");
  check(!MusicRecommendations.eligible(new PlayerService.Track("周杰伦合集","B站","bili:BV1FPjy6TEiE",180000),Collections.emptyList(),Collections.emptySet(),Collections.emptyList()),"compilations excluded");check(!MusicRecommendations.eligible(new PlayerService.Track("片段","B站","bili:BV1FPjy6TEiE",15000),Collections.emptyList(),Collections.emptySet(),Collections.emptyList()),"short clips excluded");check(MusicRecommendations.duration("03:40")==220000 && MusicRecommendations.duration("1:02:03")==3723000 && MusicRecommendations.duration("bad")==0,"search duration parsing");
  Memory boundedDisk=new Memory();ListeningHistory bounded=new ListeningHistory(boundedDisk);for(int i=0;i<305;i++)bounded.record(song("s","artist","bounded"+i),30000,true,i);check(new JSONArray(boundedDisk.value).length()==300,"bounded history");
  DevicePlaybackRecoveryCheck.Store context=new DevicePlaybackRecoveryCheck.Store();context.getSharedPreferences("library",0).edit().putString("playlists",snapshot).putString("history",historySnapshot).apply();context.getSharedPreferences("favorites",0).edit().putString("items",likesDisk.value).apply();
  String full=LibraryBackup.capture(context);LibraryBackup.Data backup=LibraryBackup.parse(full);check(backup.playlists.length()==1 && backup.history.length()==1,"portable backup includes playlists and history");LibraryBackup.Data legacy=LibraryBackup.parse(LibraryBackup.encode(new JSONArray(),new JSONArray(),0));check(legacy.playlists.length()==0 && legacy.history.length()==0,"old backups remain compatible");
  JSONObject malformed=new JSONObject(full);malformed.getJSONArray("playlists").getJSONObject(0).getJSONArray("tracks").getJSONObject(0).put("url","file:///private/key");boolean bad=false;try{LibraryBackup.parse(malformed.toString());}catch(Exception e){bad=true;}check(bad,"playlist backup validates all sources before restore");
  Player player=new Player(context);Field favoriteField=PlayerService.class.getDeclaredField("favorites");favoriteField.setAccessible(true);favoriteField.set(player,new FavoriteStore(likesDisk));player.restoreLibrary(backup);player.restoreLibrary(backup);check(player.playlists().list().size()==1 && player.listeningHistory().get(0).plays==2,"service merge is repeat-safe");
  player.tracks.add(c);player.playPlaylist(Arrays.asList(a,b),1);check(player.tracks.size()==2 && player.current()==b && player.requested==1 && favorites.contains(a.url),"playlist playback follows clicked row without editing favorites");
  restoredHistory.clear();check(restoredHistory.ranked(wall).isEmpty() && new ListeningHistory(historyDisk).ranked(wall).isEmpty(),"clear history persists");
 }
}
